// Update commits one closed bar (inHigh, inLow and inClose) and returns the new
// value. It returns [BadParam] for a bar value that is not finite and
// [OutOfRangeEndIndex] once OutRange reaches bar [IndexMax], both before
// anything changes.
func (sp *NATRStream) Update(inHigh, inLow, inClose float64) (float64, error) {
	if sp.outRangeBegIdx+sp.outRangeCount > IndexMax {
		return 0, OutOfRangeEndIndex
	}
	if (inHigh-inHigh)+(inLow-inLow)+(inClose-inClose) != 0 {
		return 0, BadParam
	}
	sp.outRangeCount++
	var tempValue float64
	var val2 float64
	var val3 float64
	var greatest float64
	var tempCY float64
	var tempLT float64
	var tempHT float64
	tempLT = inLow
	tempHT = inHigh
	tempCY = sp.lag1_inClose
	greatest = tempHT - tempLT
	val2 = math.Abs(tempCY - tempHT)
	if val2 > greatest {
		greatest = val2
	}
	val3 = math.Abs(tempCY - tempLT)
	if val3 > greatest {
		greatest = val3
	}
	sp.prevATR = math.FMA(sp.wBeta, sp.prevATR, float64(sp.wAlpha*greatest))
	if sp.optInTimePeriod <= 1 {
		sp.cur_outReal = sp.prevATR
	} else {
		tempValue = inClose
		if tempValue != 0.0 {
			sp.cur_outReal = float64(sp.prevATR / tempValue * 100.0)
		} else {
			sp.cur_outReal = 0.0
		}
	}
	sp.lag1_inClose = inClose
	return sp.cur_outReal, nil
}

// Peek returns what Update would return for the bar (inHigh, inLow and
// inClose), changing nothing. It returns [BadParam] for a bar value that is not
// finite.
func (sp *NATRStream) Peek(inHigh, inLow, inClose float64) (float64, error) {
	if (inHigh-inHigh)+(inLow-inLow)+(inClose-inClose) != 0 {
		return 0, BadParam
	}
	var tempValue float64
	var val2 float64
	var val3 float64
	var greatest float64
	var tempCY float64
	var tempLT float64
	var tempHT float64
	var cur_outReal float64
	prevATR := sp.prevATR
	tempLT = inLow
	tempHT = inHigh
	tempCY = sp.lag1_inClose
	greatest = tempHT - tempLT
	val2 = math.Abs(tempCY - tempHT)
	greatest = selF(val2 > greatest, val2, greatest)
	val3 = math.Abs(tempCY - tempLT)
	greatest = selF(val3 > greatest, val3, greatest)
	prevATR = math.FMA(sp.wBeta, prevATR, float64(sp.wAlpha*greatest))
	if sp.optInTimePeriod <= 1 {
		cur_outReal = prevATR
	} else {
		tempValue = inClose
		if tempValue != 0.0 {
			cur_outReal = float64(prevATR / tempValue * 100.0)
		} else {
			cur_outReal = 0.0
		}
	}
	return cur_outReal, nil
}

// Value returns the value at the last bar of OutRange; Peek does not change it.
func (sp *NATRStream) Value() float64 {
	return sp.cur_outReal
}

// Clone returns an independent copy of the stream at the same bar: the two
// evolve separately and share only the [Core].
func (sp *NATRStream) Clone() *NATRStream {
	cl := *sp
	return &cl
}

