func (c *Core) natrOpenAndFillInternal(inHigh, inLow, inClose []float64, startIdx, optInTimePeriod int32, outBegIdx, outNBElement *int32, outReal []float64) (*NATRStream, error) {
	sp := &NATRStream{core: c}
	if retCode := c.natrOpenImpl(sp, inHigh, inLow, inClose, startIdx, optInTimePeriod, outBegIdx, outNBElement, outReal, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) natrOpenInternal(inHigh, inLow, inClose []float64, startIdx, optInTimePeriod int32) (*NATRStream, error) {
	sp := &NATRStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outReal [1]float64
	if retCode := c.natrOpenImpl(sp, inHigh, inLow, inClose, startIdx, optInTimePeriod, &outBegIdx, &outNBElement, sink_outReal[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// NATROpen opens a live [NATRStream] on a warm-up history, oldest bar first,
// and returns it with its value at the last history bar, the value [Core.NATR]
// writes there.
//
// inHigh, inLow and inClose are the histories, of one length; the parameters
// are those of [Core.NATR].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.NATRLookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for a parameter out of range or histories
// of different lengths.
func (c *Core) NATROpen(inHigh, inLow, inClose []float64, optInTimePeriod int) (*NATRStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.natrOpenInternal(inHigh, inLow, inClose, 0, int32(optInTimePeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// NATROpenAndFill opens a stream as [Core.NATROpen] does and also writes the
// outputs over the whole history, as [Core.NATR] writes them for bars 0 through
// len(inHigh)-1, returning that range.
//
// Each output must hold len(inHigh) minus [Core.NATRLookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.NATROpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) NATROpenAndFill(inHigh, inLow, inClose []float64, optInTimePeriod int, outReal []float64) (*NATRStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.natrLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inHigh) || sameStart(outReal, inLow) || sameStart(outReal, inClose) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outReal, inHigh) || overlaps(outReal, inLow) || overlaps(outReal, inClose)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.natrOpenAndFillInternal(inHigh, inLow, inClose, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
